<script>
 import {onMount} from 'svelte';
 import {goto} from '$app/navigation';
 import {Leaf,LayoutDashboard,CalendarDays,Users,HeartHandshake,Plus,LogOut,Menu,X,Clock,Check,ShieldCheck,Search,RefreshCw,UserRound,ArrowUpRight} from 'lucide-svelte';
 import {supabase,api} from './auth.js';
 import {ROLE_LABEL,ROLE_PATH} from './config.js';
 export let expectedRole;
 let profile=null,loading=true,page='Ringkasan',mobile=false,notice='',failure='',busy=false;
 let appointments=[],accounts=[],services=[],audit=[],search='',modal=false;
 let serviceId='',customerId='',startsAt='',name='',phone='';
 const statusLabel={pending:'Menunggu',confirmed:'Dikonfirmasi',in_progress:'Berlangsung',completed:'Selesai',cancelled:'Dibatalkan'};
 const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n);
 const dateText=d=>new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Jakarta',dateStyle:'medium',timeStyle:'short'}).format(new Date(d))+' WIB';
 const initials=n=>(n||'A').split(' ').map(n=>n[0]).slice(0,2).join('').toUpperCase();
 $: isAdmin=profile?.role==='administrator';
 $: isCustomer=profile?.role==='customer';
 $: isTherapist=profile?.role==='therapist';
 $: menu=[{name:'Ringkasan',icon:LayoutDashboard},{name:'Reservasi',icon:CalendarDays},{name:'Layanan',icon:Leaf},...(isAdmin?[{name:'Kelola Akun',icon:Users},{name:'Riwayat Akses',icon:ShieldCheck}]:[]),{name:'Profil Saya',icon:UserRound}];
 $: filtered=appointments.filter(a=>((a.customer?.full_name||'')+' '+(a.service?.name||'')+' '+(a.therapist?.full_name||'')).toLowerCase().includes(search.toLowerCase()));
 $: therapists=accounts.filter(a=>a.role==='therapist'&&a.active);
 $: customers=accounts.filter(a=>a.role==='customer'&&a.active);
 $: visibleAccounts=accounts.filter(a=>(a.full_name+' '+a.email+' '+ROLE_LABEL[a.role]).toLowerCase().includes(search.toLowerCase()));
 onMount(()=>{boot();const {data:{subscription}}=supabase.auth.onAuthStateChange(event=>{if(event==='SIGNED_OUT'){profile=null;appointments=[];accounts=[];audit=[];goto('/');}});const sync=()=>{if(document.visibilityState==='visible')boot(false);};document.addEventListener('visibilitychange',sync);return()=>{subscription.unsubscribe();document.removeEventListener('visibilitychange',sync);};});
 async function boot(initial=true){if(initial)loading=true;failure='';try{
  const result=await api('/me');
  if(result.profile.role!==expectedRole){window.location.replace(ROLE_PATH[result.profile.role]);return;}
  profile=result.profile;name=profile.full_name;phone=profile.phone;
  await loadData();
 }catch(e){failure=e.message;if(e.status===401||e.status===403||e.message.includes('login')){profile=null;appointments=[];accounts=[];audit=[];await goto('/',{replaceState:true});}}finally{loading=false;}}
 async function loadData(){const r=await Promise.all([api('/appointments'),api('/services'),...(profile.role==='administrator'?[api('/accounts'),api('/role-audit')]:[])]);appointments=r[0].appointments;services=r[1].services;if(r[2]){accounts=r[2].accounts;audit=r[3].audit;}}
 async function act(action,message){busy=true;failure='';notice='';try{await action();await boot(false);notice=message;}catch(e){failure=e.message;if(e.status===401||e.status===403)await boot(false);}finally{busy=false;}}
 async function logout(){busy=true;try{const {error}=await supabase.auth.signOut();if(error)throw error;profile=null;appointments=[];accounts=[];audit=[];await goto('/');}catch{failure='Keluar belum berhasil. Coba lagi.';}finally{busy=false;}}
 function openBooking(){serviceId=services[0]?.id||'';customerId=customers[0]?.id||'';startsAt='';modal=true;}
 async function saveBooking(){if(!startsAt)return;await act(async()=>{await api('/appointments',{method:'POST',body:JSON.stringify({service_id:serviceId,customer_id:customerId,starts_at:new Date(startsAt+'+07:00').toISOString()})});modal=false;},'Reservasi tersimpan. Administrator akan menentukan terapis.');}
 function changeStatus(id,status){act(()=>api('/appointments/'+id+'/status',{method:'PATCH',body:JSON.stringify({status})}),'Status sesi diperbarui.');}
 function assign(id,therapistId){if(therapistId)act(()=>api('/appointments/'+id+'/therapist',{method:'PATCH',body:JSON.stringify({therapist_id:therapistId})}),'Terapis ditugaskan dan reservasi dikonfirmasi.');}
 function updateAccount(a,role,active){if(role==='administrator'&&a.role!=='administrator'&&!window.confirm('Berikan akses administrator kepada '+a.email+'? Akun ini dapat mengelola akun lain dan seluruh reservasi.'))return;act(()=>api('/accounts/'+a.id,{method:'PATCH',body:JSON.stringify({role,active})}),'Hak akses akun diperbarui.');}
 function saveProfile(){act(()=>api('/me',{method:'PATCH',body:JSON.stringify({full_name:name,phone})}),'Profil berhasil disimpan.');}
</script>
<svelte:head><title>Dashboard {ROLE_LABEL[expectedRole]} — Rumah Sehat Kakang</title><meta name="robots" content="noindex,nofollow"/></svelte:head>
{#if loading}<div class="loading"><Leaf size={38}/><h1>Menyiapkan dashboard…</h1><p>Memeriksa sesi dan hak akses Anda.</p></div>{:else if !profile}<div class="loading"><h1>Login diperlukan</h1><p>{failure||'Masuk untuk melanjutkan.'}</p><a href="/">Ke halaman login</a></div>{:else}
<div class="app"><aside class:open={mobile}><a class="brand" href={ROLE_PATH[profile.role]}><span class="brand-icon"><Leaf size={26}/></span><span>RUMAH SEHAT<strong>KAKANG.</strong></span></a><div class="workspace"><ShieldCheck size={20}/><div>{ROLE_LABEL[profile.role]}<small>Akses sesuai peran akun</small></div></div><p class="navlabel">MENU UTAMA</p><nav>{#each menu as item}<button class:active={page===item.name} onclick={()=>{page=item.name;search='';mobile=false;}}><item.icon size={19}/>{item.name}</button>{/each}</nav><div class="aside-bottom"><div class="care"><Leaf size={24}/><h3>Sehat dimulai dari jeda.</h3><p>Merawat Sebelum Sakit,<br/>Ikhtiar Supaya Sehat.</p></div><button class="logout" disabled={busy} onclick={logout}><LogOut size={18}/>Keluar akun</button><div class="profile"><span class="avatar">{initials(profile.full_name)}</span><div><strong>{profile.full_name||'Akun Saya'}</strong><small>{ROLE_LABEL[profile.role]}</small></div></div></div></aside>
<main><header><div class="breadcrumb"><button class="mobile-menu" onclick={()=>mobile=!mobile} aria-label="Buka menu"><Menu size={22}/></button>Dashboard <span>/</span><b>{page}</b></div><div class="header-right"><span class="role-badge"><ShieldCheck size={14}/>{ROLE_LABEL[profile.role]}</span><button class="refresh" disabled={busy} onclick={()=>act(async()=>{},'Data diperbarui.')} aria-label="Perbarui data"><RefreshCw size={18}/></button></div></header><div class="content"><div class="heading"><div><p class="eyebrow">RUMAH SEHAT KAKANG</p><h1>{page==='Ringkasan'?'Halo, '+(profile.full_name||'Selamat datang'):page}<span class="gold">.</span></h1><p class="subtitle">{isAdmin?'Kelola akun, penugasan terapis, dan seluruh reservasi.':isTherapist?'Jadwal dan pelanggan yang ditugaskan khusus untuk Anda.':'Jadwal refleksi dan riwayat reservasi pribadi Anda.'}</p></div>{#if !isTherapist}<button class="primary" onclick={openBooking}><Plus size={18}/>Reservasi baru</button>{/if}</div>
{#if failure}<div class="notice error" role="alert">{failure}<button onclick={()=>failure=''} aria-label="Tutup pesan"><X size={16}/></button></div>{/if}{#if notice}<div class="notice" role="status">{notice}<button onclick={()=>notice=''} aria-label="Tutup pesan"><X size={16}/></button></div>{/if}
{#if page==='Ringkasan'}<section class="welcome"><div><span class="pill">RUANG UNTUK KEMBALI NYAMAN</span><h2>{isAdmin?'Pelayanan rapi. Akses terjaga.':isTherapist?'Hadir dengan sepenuh hati.':'Luangkan waktu untuk diri Anda.'}</h2><p>{isAdmin?'Setiap akun punya peran. Setiap sesi mendapatkan perhatian.':isTherapist?'Lihat penugasan Anda, mulai sesi, lalu tandai selesai.':'Buat reservasi dan pantau konfirmasi jadwal dalam satu tempat.'}</p><button onclick={()=>page='Reservasi'}>Lihat reservasi <ArrowUpRight size={17}/></button></div><Leaf class="hero-leaf" size={160} strokeWidth={0.8}/></section><div class="stats"><article><span>Reservasi{isCustomer?' saya':''}</span><strong>{appointments.length}</strong><p>{isAdmin?'Seluruh reservasi':'Dalam akses akun Anda'}</p></article><article><span>Menunggu</span><strong>{appointments.filter(a=>a.status==='pending').length}</strong><p>Menunggu konfirmasi admin</p></article><article><span>Sedang berlangsung</span><strong>{appointments.filter(a=>a.status==='in_progress').length}</strong><p>Sesi sedang dilayani</p></article><article><span>Selesai</span><strong>{appointments.filter(a=>a.status==='completed').length}</strong><p>Sesi yang telah selesai</p></article></div>{/if}
{#if page==='Ringkasan'||page==='Reservasi'}<section class="panel"><div class="panel-heading"><div><h2>{isTherapist?'Penugasan saya':isCustomer?'Reservasi saya':'Daftar reservasi'}</h2><p>{isAdmin?'Penugasan dan status seluruh pelanggan':'Data dibatasi sesuai akun Anda'} · Waktu WIB</p></div><span class="muted">{appointments.length} sesi</span></div><div class="search"><Search size={18}/><input bind:value={search} placeholder="Cari pelanggan atau layanan…" aria-label="Cari reservasi"/></div><div class="table-wrap"><table><thead><tr>{#if !isCustomer}<th>PELANGGAN</th>{/if}<th>LAYANAN & JADWAL</th><th>TERAPIS</th><th>STATUS</th><th>AKSI</th></tr></thead><tbody>{#each filtered as a}<tr>{#if !isCustomer}<td><strong>{a.customer?.full_name||'Customer'}</strong><small>{a.customer?.phone||'Nomor belum diisi'}</small></td>{/if}<td><strong>{a.service?.name||'Layanan refleksi'}</strong><small>{dateText(a.starts_at)}</small><small>{a.duration_minutes} menit · {money(a.price)}</small></td><td>{a.therapist?.full_name||'Belum ditugaskan'}</td><td><span class={'status '+a.status}>{statusLabel[a.status]}</span></td><td><div class="actions">{#if isAdmin && ['pending','confirmed'].includes(a.status)}<select aria-label={'Tugaskan terapis untuk '+(a.customer?.full_name||'customer')} disabled={busy} value={a.therapist_id||''} onchange={e=>assign(a.id,e.currentTarget.value)}><option value="" disabled>Pilih terapis</option>{#each therapists as t}<option value={t.id}>{t.full_name||t.email}</option>{/each}</select>{/if}{#if a.status==='confirmed' && !isCustomer}<button class="outline" disabled={busy} onclick={()=>changeStatus(a.id,'in_progress')}>Mulai sesi</button>{/if}{#if a.status==='in_progress' && !isCustomer}<button class="outline" disabled={busy} onclick={()=>changeStatus(a.id,'completed')}><Check size={15}/>Selesai</button>{/if}{#if isAdmin && !['completed','cancelled'].includes(a.status)}<button class="danger-link" disabled={busy} onclick={()=>changeStatus(a.id,'cancelled')}>Batalkan</button>{/if}{#if isCustomer}<span class="muted">{a.status==='pending'?'Menunggu admin':'Lihat status sesi'}</span>{/if}</div></td></tr>{:else}<tr><td colspan={isCustomer?4:5}><div class="empty"><CalendarDays size={31}/><h3>Belum ada reservasi</h3><p>{search?'Tidak ada data yang cocok.':isTherapist?'Sesi yang ditugaskan admin akan muncul di sini.':'Reservasi yang dibuat akan muncul di sini.'}</p></div></td></tr>{/each}</tbody></table></div><div class="table-footer">Menampilkan hingga 300 reservasi terbaru yang dapat diakses akun Anda.</div></section>{/if}
{#if page==='Layanan'}<div class="service-grid">{#each services as s}<section class="panel service-card"><Leaf size={36}/><h2>{s.name}</h2><p>{s.description}</p><div class="duration"><Clock size={16}/>{s.duration_minutes} menit</div><strong>{money(s.price)}</strong>{#if !isTherapist}<button class="primary" onclick={()=>{openBooking();serviceId=s.id;}}>Buat reservasi <Plus size={16}/></button>{/if}</section>{/each}</div>{/if}
{#if page==='Kelola Akun'&&isAdmin}<section class="panel"><div class="panel-heading"><div><h2>Kelola peran & akses</h2><p>Customer daftar sendiri. Ubah akun terverifikasi menjadi terapis atau administrator.</p></div></div><div class="search"><Search size={18}/><input bind:value={search} placeholder="Cari nama, email, atau peran…" aria-label="Cari akun"/></div><div class="table-wrap"><table><thead><tr><th>AKUN</th><th>PERAN</th><th>STATUS</th><th>AKSES</th></tr></thead><tbody>{#each visibleAccounts as a}<tr><td><strong>{a.full_name||'Nama belum diisi'}</strong><small>{a.email}</small></td><td>{#if a.id===profile.id}<span class="role-badge">Administrator</span>{:else}<select aria-label={'Peran '+a.email} value={a.role} disabled={busy} onchange={e=>updateAccount(a,e.currentTarget.value,a.active)}><option value="customer">Customer</option><option value="therapist">Terapis</option><option value="administrator">Administrator</option></select>{/if}</td><td><span class="status" class:completed={a.active} class:cancelled={!a.active}>{a.active?'Aktif':'Nonaktif'}</span></td><td>{#if a.id!==profile.id}<button class="outline" disabled={busy} onclick={()=>updateAccount(a,a.role,!a.active)}>{a.active?'Nonaktifkan':'Aktifkan'}</button>{:else}<span class="muted">Akun Anda dilindungi</span>{/if}</td></tr>{:else}<tr><td colspan="4" class="empty">Tidak ada akun yang cocok.</td></tr>{/each}</tbody></table></div><div class="table-footer">Menampilkan hingga 500 akun terbaru. Perubahan peran tercatat di Riwayat Akses.</div></section>{/if}
{#if page==='Riwayat Akses'&&isAdmin}<section class="panel"><div class="panel-heading"><div><h2>Riwayat perubahan akses</h2><p>100 perubahan terakhir oleh administrator.</p></div></div><div class="table-wrap"><table><thead><tr><th>WAKTU</th><th>AKUN</th><th>PERUBAHAN</th><th>OLEH</th></tr></thead><tbody>{#each audit as a}<tr><td>{dateText(a.created_at)}</td><td>{accounts.find(x=>x.id===a.target_id)?.email||a.target_id}</td><td>{ROLE_LABEL[a.old_role]} → {ROLE_LABEL[a.new_role]}<small>{a.active?'Aktif':'Nonaktif'}</small></td><td>{accounts.find(x=>x.id===a.actor_id)?.full_name||'Administrator'}</td></tr>{:else}<tr><td colspan="4" class="empty">Belum ada perubahan hak akses.</td></tr>{/each}</tbody></table></div></section>{/if}
{#if page==='Profil Saya'}<section class="panel profile-panel"><h2>Profil saya</h2><p class="muted">Peran: <strong>{ROLE_LABEL[profile.role]}</strong></p><form onsubmit={e=>{e.preventDefault();saveProfile();}}><label>Email<input value={profile.email} disabled/></label><label>Nama lengkap<input required maxlength="100" bind:value={name} autocomplete="name"/></label><label>Nomor WhatsApp<input maxlength="25" type="tel" pattern="[+0-9 ()-]*" bind:value={phone} autocomplete="tel"/></label><button class="primary" disabled={busy}>{busy?'Menyimpan…':'Simpan profil'}</button></form></section>{/if}
<footer><span>© 2026 Rumah Sehat Kakang</span><span><ShieldCheck size={14}/>Akses terlindungi sesuai peran</span></footer></div></main></div>
{#if modal}<div class="overlay" role="presentation"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="booking-title" tabindex="-1"><div class="panel-heading"><div><p class="eyebrow">RESERVASI REFLEKSI</p><h2 id="booking-title">Jadwalkan waktu Anda</h2></div><button onclick={()=>modal=false} aria-label="Tutup formulir"><X size={22}/></button></div><p class="muted">Pilih waktu dalam WIB. Administrator akan mengonfirmasi dan menentukan terapis.</p>{#if failure}<div class="notice error" role="alert">{failure}</div>{/if}<form onsubmit={e=>{e.preventDefault();saveBooking();}}>{#if isAdmin}<label>Customer<select required bind:value={customerId}><option value="" disabled>Pilih customer</option>{#each customers as c}<option value={c.id}>{c.full_name||c.email}</option>{/each}</select></label>{/if}<label>Layanan<select required bind:value={serviceId}>{#each services as s}<option value={s.id}>{s.name} · {money(s.price)}</option>{/each}</select></label><label>Tanggal dan jam (WIB)<input required type="datetime-local" bind:value={startsAt}/></label><div class="booking-total"><span>Harga layanan</span><strong>{money(services.find(s=>s.id===serviceId)?.price||0)}</strong></div><button class="primary" disabled={busy||!services.length||(isAdmin&&!customers.length)}>{busy?'Menyimpan…':'Simpan reservasi'}</button>{#if isAdmin&&!customers.length}<p class="muted">Belum ada customer aktif. Minta customer mendaftar terlebih dahulu.</p>{/if}</form></div></div>{/if}
{/if}
<style>
:global(*){box-sizing:border-box}:global(body){margin:0;background:#f7f8f3;color:#243e2d;font-family:Arial,Helvetica,sans-serif;font-size:15px}:global(button),:global(input),:global(select){font:inherit}:global(button){cursor:pointer}:global(button:disabled){opacity:.55;cursor:wait}:global(button:focus-visible),:global(a:focus-visible){outline:3px solid #bda15a;outline-offset:3px}button{border:0;background:none;color:inherit}input,select{padding:11px 12px;border:1px solid #dbe3d2;border-radius:6px;background:#fff;color:#2c4732;font-size:13px;max-width:100%}input:focus,select:focus{outline:2px solid #7f9b6d;outline-offset:2px}.app{display:flex;min-height:100vh}aside{width:248px;position:fixed;inset:0 auto 0 0;background:white;border-right:1px solid #e3e9db;padding:30px 22px 20px;display:flex;flex-direction:column;z-index:20}.brand{display:flex;gap:11px;align-items:center;color:#2f5139;text-decoration:none;font-size:9px;letter-spacing:1px;font-weight:750}.brand strong{display:block;font-size:25px;letter-spacing:-.5px;margin-top:3px}.brand-icon{border:1px solid #b9c8ab;border-radius:50%;padding:10px;display:grid;place-items:center}.workspace{display:flex;align-items:center;gap:12px;background:#f1f4ea;border:1px solid #e1e7d8;border-radius:7px;padding:14px 12px;margin-top:32px;font-size:13px;font-weight:700}.workspace small,.profile small{display:block;font-size:11px;color:#65785a;margin-top:6px;font-weight:500}.navlabel{font-size:10px;color:#718361;font-weight:750;letter-spacing:1px;margin:28px 12px 14px}nav{display:grid;gap:7px}nav button{display:flex;align-items:center;gap:12px;text-align:left;padding:13px 12px;font-size:14px;font-weight:650;color:#5d7350;border-radius:6px}nav button.active{background:#eaf0e3;color:#294c32;font-weight:800}nav button:hover{background:#f0f4e9}.aside-bottom{margin-top:auto;padding-top:30px}.care{background:#f1f2e6;padding:20px 15px;border-radius:8px;color:#778452}.care h3{font-size:17px;line-height:1.4;color:#50613c}.care p{font-size:12